import path from "node:path";
import process from "node:process";
import { createJiti } from "jiti";
import { lilconfig } from "lilconfig";
import { defuOverrideArray } from "@weapp-tailwindcss/shared";
//#region src/index.ts
const jiti = createJiti(import.meta.url);
async function loadConfig(options) {
	const { config, cwd, moduleName } = defuOverrideArray(options, {
		cwd: process.cwd(),
		moduleName: "tailwind"
	});
	const searcher = lilconfig("tailwindcss", {
		searchPlaces: [
			`${moduleName}.config.js`,
			`${moduleName}.config.cjs`,
			`${moduleName}.config.mjs`,
			`${moduleName}.config.ts`,
			`${moduleName}.config.cts`,
			`${moduleName}.config.mts`
		],
		loaders: {
			".js": jiti,
			".cjs": jiti,
			".mjs": jiti,
			".ts": jiti,
			".cts": jiti,
			".mts": jiti
		}
	});
	if (typeof config === "string" && config) {
		const configPath = path.isAbsolute(config) ? config : path.resolve(cwd, config);
		return await searcher.load(configPath);
	} else return await searcher.search(cwd);
}
//#endregion
export { loadConfig };
